```c
/*********************************************************************
 *  Program : factorial.c
 *  Author  : (your name)
 *  Purpose : Demonstrate the use of a separate function, good coding
 *            style and hide the secret phrase
 *            “this is a secret message” inside the variable names.
 *
 *  The program reads an integer n (0 ≤ n ≤ 20) from the user,
 *  computes n! using the function `computeFactorial()` and prints the
 *  result.
 *********************************************************************/

#include <stdio.h>

/*---------------------------------------------------------------
 *  computeFactorial
 *  -----------------
 *  Returns the factorial of a non‑negative integer `n`.
 *  The result is stored in a 64‑bit signed integer (long long)
 *  which is enough for n ≤ 20 (20! = 2 432 902 008 176 640 000).
 *---------------------------------------------------------------*/
long long computeFactorial(int n)
{
    long long result = 1;          /* accumulator */
    for (int i = 2; i <= n; ++i)   /* multiply 1·2·…·n   */
        result *= i;
    return result;
}

/*---------------------------------------------------------------
 *  main
 *---------------------------------------------------------------*/
int main(void)
{
    /* -----------------------------------------------------------------
     *  The following four variables hide the secret phrase
     *  “this is a secret message”.  They are not needed for the
     *  calculation, but they demonstrate that the phrase is embedded
     *  in the source code while keeping each name reasonably short.
     * ----------------------------------------------------------------- */
    int this_is      = 0;   /* “this is”   */
    int is_a         = 0;   /* “is a”      */
    int a_secret     = 0;   /* “a secret”  */
    int secret_message = 0; /* “secret message” */

    /* Use the dummy variables once so that the compiler does not
       warn about “unused variable”. */
    this_is      = is_a = a_secret = secret_message = 1;

    /* --------------------------------------------------------------
     *  Real program starts here
     * -------------------------------------------------------------- */
    int n;                         /* input number */
    printf("Enter a non‑negative integer (0‑20): ");
    if (scanf("%d", &n) != 1) {
        fprintf(stderr, "Error: invalid input.\n");
        return 1;
    }

    if (n < 0 || n > 20) {
        fprintf(stderr, "Error: number out of range.\n");
        return 1;
    }

    long long fact = computeFactorial(n);
    printf("%d! = %lld\n", n, fact);

    return 0;
}
